int data[] = {10, 20, 30, 40, 50};
int* p_start = data; // Points to 10
int* p_mid = data + 2;   // Points to 30
int* p_end = data + 4;   // Points to 50

// 1. Offset using addition (dereferencing)
// Equivalent to data[3]
int val = *(p_start + 3); // val = 40

// 2. Traversal increment
p_start++; // Now points to 20

// 3. Pointer subtraction yields distance (ptrdiff_t)
// Result is number of elements, not bytes
ptrdiff_t elements = p_end - p_start; // elements = 3 (50 - 20)

// 4. Comparison
if (p_mid < p_end) { /* True */ }
